CustomField.formula:
ROUND( 8 * (
   ( 5 * FLOOR( ( DATEVALUE( or_New_Opp_Reg_Time_Pending_CAM__c ) - DATE( 1900, 1, 8) ) / 7) +
    MIN(5, 
     MOD( DATEVALUE( or_New_Opp_Reg_Time_Pending_CAM__c ) - DATE( 1900, 1, 8), 7) +
     MIN( 1, 24 / 8 * ( MOD( or_New_Opp_Reg_Time_Pending_CAM__c - DATETIMEVALUE( '1900-01-08 16:00:00' ), 1 ) ) )
    ) 
   )
 -
   ( 5 * FLOOR( ( DATEVALUE( Lead_Owner_Changed_Timestamp__c ) - DATE( 1900, 1, 8) ) / 7) +
     MIN( 5,
      MOD( DATEVALUE( Lead_Owner_Changed_Timestamp__c ) - DATE( 1996, 1, 1), 7 ) +
      MIN( 1, 24 / 8 * ( MOD( Lead_Owner_Changed_Timestamp__c - DATETIMEVALUE( '1900-01-08 16:00:00' ), 1) ) )
    )
   ) 
  ), 
0 )
